def min_gap(react):
    dt = 0.01; xe, ve = 0.0, 15.0; xl, vl = 30.0, 15.0; g = 1e9; tt = 0.0
    while tt < 10:
        vl = max(0.0, vl - 4 * dt); xl += vl * dt
        if tt >= react: ve = max(0.0, ve - 6 * dt)
        xe += ve * dt; g = min(g, xl - xe); tt += dt
    return round(g, 2)
print(min_gap(0.5), min_gap(1.5), min_gap(3.0))  # 28.5 16.88 -5.77
